            "Fire Elementalist": {"name": "Fire Elementalist", "abbr": "FE", "description": "Fire Elementalists have learned the Foxfire spell. Their other starting spells are likewise focused on fiery and explosive destruction.", "category": "Mage", "stats": {"str": 0, "int": 7, "dex": 5}, "equipment": ["robe", "potion of magic"], "spells": ["Foxfire", "Scorch", "Volatile Blastmotes", "Inner Flame", "Flame Wave"], "skills": {"dodging": 2, "stealth": 2, "spellcasting": 2, "conjurations": 1, "fire magic": 3}, "recommended": ["Deep Elf", "Mountain Dwarf", "Naga", "Tengu", "Demigod", "Gargoyle", "Djinni"]},
            "Ice Elementalist": {"name": "Ice Elementalist", "abbr": "IE", "description": "Ice Elementalists begin with the Freeze spell. Their later spells provide strong offence and defence, but may restrict their movement.", "category": "Mage", "stats": {"str": 0, "int": 7, "dex": 5}, "equipment": ["robe", "potion of magic"], "spells": ["Freeze", "Frozen Ramparts", "Ozocubu's Armour", "Summon Ice Beast"], "skills": {"dodging": 2, "stealth": 2, "spellcasting": 2, "ice magic": 4}, "recommended": ["Merfolk", "Barachi", "Draconian", "Demigod", "Gargoyle", "Djinni", "Revenant"]},
            "Summoner": {"name": "Summoner", "abbr": "Su", "description": "Summoners are able to cast Summon Small Mammal from the start, and begin with spells to summon stronger and more exotic allies in their library.", "category": "Mage", "stats": {"str": 0, "int": 7, "dex": 5}, "equipment": ["robe", "potion of magic"], "spells": ["Summon Small Mammal", "Call Imp", "Call Canine Familiar", "Eringya's Surprising Crocodile", "Summon Seismosaurus Egg"], "skills": {"dodging": 2, "stealth": 2, "spellcasting": 2, "summonings": 4}, "recommended": ["Deep Elf", "Oni", "Vine Stalker", "Merfolk", "Tengu"]},
            "Air Elementalist": {"name": "Air Elementalist", "abbr": "AE", "description": "Air Elementalists have learned the Shock spell. Their electrical magic can harm groups of foes, while their air spells assist in fighting or fleeing enemies.", "category": "Mage", "stats": {"str": 0, "int": 7, "dex": 5}, "equipment": ["robe", "potion of magic"], "spells": ["Shock", "Aura of Resonance", "Static Discharge", "Swiftness", "Airstrike"], "skills": {"dodging": 2, "stealth": 2, "spellcasting": 2, "conjurations": 1, "air magic": 3}, "recommended": ["Deep Elf", "Tengu", "Draconian", "Naga", "Vine Stalker", "Djinni", "Gale Centaur"]},
            "Earth Elementalist": {"name": "Earth Elementalist", "abbr": "EE", "description": "Earth Elementalists know the Sandblast spell, and can later learn more earthen spells suitable for subtle stabbing or brute-force blasting.", "category": "Mage", "stats": {"str": 0, "int": 7, "dex": 5}, "equipment": ["robe", "potion of magic"], "spells": ["Sandblast", "Passwall", "Stone Arrow", "Petrify", "Brom's Barrelling Boulder"], "skills": {"dodging": 2, "stealth": 2, "spellcasting": 2, "conjurations": 1, "earth magic": 3}, "recommended": ["Deep Elf", "Spriggan", "Gargoyle", "Demigod", "Octopode", "Revenant"]},
            "Skald": {"name": "Skald", "abbr": "Sk", "description": "Skalds are warrior-poets who weave battle-songs and enchantments, empowering themselves and their allies with Song of Slaying, Shroud of Golubria, and Regeneration.", "category": "Warrior-mage", "stats": {"str": 4, "int": 5, "dex": 3}, "equipment": ["leather armour", "scroll of butterflies"], "spells": ["Song of Slaying", "Shroud of Golubria", "Aura of Zeal", "Regeneration", "Jinxbite", "Song of Fellowship"], "skills": {"fighting": 2, "dodging": 2, "spellcasting": 2, "hexes": 2, "translocations": 1, "weapon": 2}, "recommended": ["High Elf", "Merfolk", "Gnoll", "Tengu", "Barachi", "Mayflytaur"]},
            "Alchemist": {"name": "Alchemist", "abbr": "Al", "description": "Alchemists start with the Poisonous Vapours spell, and their magic is very effective against foes susceptible to poison.", "category": "Mage", "stats": {"str": 0, "int": 7, "dex": 5}, "equipment": ["robe", "potion of magic", "potion of poison ×2"], "spells": ["Poisonous Vapours", "Fulsome Distillation", "Evaporate", "Mercury Arrow", "Mephitic Cloud", "Aura of Vitality", "Olgreb's Toxic Radiance", "Sticky Flame"], "skills": {"dodging": 2, "stealth": 2, "spellcasting": 2, "conjurations": 1, "alchemy": 3}, "recommended": ["Deep Elf", "Spriggan", "Naga", "Merfolk", "Octopode", "Djinni", "Demonspawn"]},
            "Chaos Knight": {"name": "Chaos Knight", "abbr": "CK", "description": "Chaos Knights are playthings of the unpredictable Xom, and are subject to the god's constantly changing moods.", "category": "Zealot", "stats": {"str": 4, "int": 4, "dex": 4}, "equipment": ["leather armour enchantment 2", "scroll of butterflies no_exclude"], "spells": [], "skills": {"fighting": 3, "dodging": 1, "armour": 1, "weapon": 3}, "recommended": ["Spriggan", "Troll", "Gnoll", "Merfolk", "Minotaur", "Draconian", "Demonspawn"]},
            "Shapeshifter": {"name": "Shapeshifter", "abbr": "Sh", "description": "Shapeshifters use talismans to shift their form, making them powerful melee fighters (especially when unarmed) at the cost of armour.", "category": "Metamorph", "stats": {"str": 6, "int": 2, "dex": 4}, "equipment": ["animal skin", "flux bauble ×3", "potion of lignification", "quill talisman", "protean talisman"], "spells": [], "skills": {"fighting": 2, "unarmed combat": 3, "dodging": 2, "shapeshifting": 3}, "recommended": ["Naga", "Merfolk", "Draconian", "Demigod", "Demonspawn", "Troll"]},
