            "Monk": {"name": "Monk", "abbr": "Mo", "description": "Monks start with a simple weapon of their choice, an orb of light, a potion of divine ambrosia, a potion of enlightenment, and gain additional piety with the first god they worship.", "category": "Warrior", "stats": {"str": 3, "int": 2, "dex": 7}, "equipment": ["robe", "potion of ambrosia", "potion of enlightenment", "orb ego:light"], "spells": [], "skills": {"fighting": 3, "dodging": 3, "weapon": 3}, "recommended": ["Mountain Dwarf", "Troll", "Merfolk", "Gargoyle", "Demonspawn", "Gale Centaur"]},
